$cols=['tourist_id','booking_domain','booking_id','initiated_by','booking_reference','booking_type','service_name','service_date','original_service_date','total_amount','amount_paid','days_before_service','refund_policy','refundable_amount','non_refundable_amount','request_status','refund_status','cancellation_reason','admin_note','reschedule_offered','tourist_decision','reviewed_by_admin_id','reviewed_at','refund_updated_at','refund_request_created_at','decision_deadline','rescheduled_service_date','provider_email_last_sent_at','refund_destination_last4'];
