foreach(['admin','operator','hotel_admin']as$role)foreach([0,400,2000]as$paid){$p=fixture();$hotel=$role==='hotel_admin';$p->exec($hotel?'UPDATE hotel_room_bookings SET amount_paid='.$paid:'UPDATE bookings SET payment_amount='.$paid);$r=BookingRejectAndQueue($p,$role,$role==='operator'?7:1,$hotel?2:1,'Resource unavailable <test>',$hotel?9:0);$q=$r['request'];check($r['created'],'Creates decision');check($q['request_status']==='approved','Auto-approved cancellation');check((float)$q['refundable_amount']===$paid*1.0,'Entire paid amount refunded regardless of late date');check($q['refund_status']===($paid?'pending':'not_applicable'),'Correct refund stage');check($q['refund_policy']===($paid?'provider_full_refund':'no_payment'),'Correct provider policy');check($q['cancellation_reason']==='Resource unavailable <test>','Reason saved');check($p->query($hotel?'SELECT booking_status FROM hotel_room_bookings':'SELECT is_complete FROM bookings')->fetchColumn()==='cancelled','Canonical cancellation status');check($p->query($hotel?'SELECT amount_paid FROM hotel_room_bookings':'SELECT payment_amount FROM bookings')->fetchColumn()==$paid,'Financial amounts unchanged');
$sent=0;check(BookingRejectionNotify($p,$r,function($req,$guest)use(&$sent){$sent++;check($guest['email']==='tourist@example.test','Recipient read from database');return true;}),'Email sent');check($sent===1,'Single email');$repeat=BookingRejectAndQueue($p,$role,$role==='operator'?7:1,$hotel?2:1,'Repeated reason',$hotel?9:0);check(!$repeat['created'],'Repeat idempotent');BookingRejectionNotify($p,$repeat,function()use(&$sent){$sent++;return true;});check($sent===1,'No duplicate email');check((int)$p->query('SELECT COUNT(*) FROM booking_cancellation_requests')->fetchColumn()===1,'No duplicate refund request');$email=BookingRejectionEmailContent($q,['full_name'=>'Guest <x>']);check(strpos($email['html'],'Resource unavailable &lt;test&gt;')!==false,'Escaped reason');check(strpos($email['html'],'Guest &lt;x&gt;')!==false,'Escaped guest');check(strpos($email['plain'],'Resource unavailable <test>')!==false,'Plain-text reason');check(strpos($email['html'],'Cancellation status')!==false,'Approved status in email');}
$p=fixture();denied(fn()=>BookingRejectAndQueue($p,'operator',8,1,'Not available'));denied(fn()=>BookingRejectAndQueue($p,'hotel_admin',1,2,'Not available',8));check((int)$p->query('SELECT COUNT(*) FROM booking_cancellation_requests')->fetchColumn()===0,'Ownership failure leaves no refund');
foreach(['',str_repeat('a',1501)]as$reason)denied(fn()=>BookingRejectionReason(['rejection_reason'=>$reason]));denied(fn()=>BookingRejectionReason(['decision_category'=>'Other','decision_note'=>'']));check(BookingRejectionReason(['decision_category'=>'Other','decision_note'=>'Safety issue'])==='Safety issue','Custom reason required');check(BookingRejectionReason(['decision_category'=>'Boat unavailable','decision_note'=>'Repair'])==='Boat unavailable - Repair','Category and detail saved');
$p=fixture();$p->exec("INSERT INTO payment_transactions VALUES(1,'package',1,'pending')");denied(fn()=>BookingRejectAndQueue($p,'admin',1,1,'Unavailable'));check((int)$p->query('SELECT COUNT(*) FROM booking_cancellation_requests')->fetchColumn()===0,'Active checkout blocks rejection');check($p->query('SELECT status FROM bookings')->fetchColumn()==='pending','Failed decision leaves booking unchanged');
$p=fixture();$p->exec("UPDATE bookings SET status='accepted'");denied(fn()=>BookingRejectAndQueue($p,'operator',7,1,'Unavailable'));
$p=fixture();$p->exec("UPDATE hotel_room_bookings SET booking_status='confirmed',checked_in_at='2026-10-20'");denied(fn()=>BookingRejectAndQueue($p,'hotel_admin',1,2,'Unavailable',9));
$p=fixture();$r=BookingRejectAndQueue($p,'admin',1,1,'Unavailable');check(!BookingRejectionNotify($p,$r,fn()=>false),'Email failure reported');check($p->query('SELECT request_status FROM booking_cancellation_requests')->fetchColumn()==='approved','Email failure preserves approved refund');check($p->query('SELECT provider_email_sent_count FROM booking_cancellation_requests')->fetchColumn()==0,'Failure not marked delivered');
$p=fixture();$p->exec("UPDATE hotel_room_bookings SET tourist_id=0");$r=BookingRejectAndQueue($p,'hotel_admin',1,2,'Unavailable',9);check(BookingRejectionRecipient($p,$r['request'],$r['booking'])['email']==='guest@example.test','Unlinked hotel guest email supported');
$p=fixture();$p->exec("CREATE TRIGGER block_update BEFORE UPDATE ON bookings BEGIN SELECT RAISE(ABORT,'fixture failure'); END");denied(fn()=>BookingRejectAndQueue($p,'admin',1,1,'Unavailable'));check((int)$p->query('SELECT COUNT(*) FROM booking_cancellation_requests')->fetchColumn()===0,'Booking update failure rolls back refund request');
$p=fixture();$p->exec("INSERT INTO booking_cancellation_requests(booking_domain,booking_id,request_status,refund_status,refund_destination_last4) VALUES('tour',1,'pending','not_started','1234')");$r=BookingRejectAndQueue($p,'admin',1,1,'Unavailable');check($r['request']['refund_destination_last4']==='1234','Existing destination retained');check((int)$p->query('SELECT COUNT(*) FROM booking_cancellation_requests')->fetchColumn()===1,'Existing pending tourist request upgraded');
